const ourStoryEn = `Generations of Knowledge, From Damascus to Europe

The story of Jleilati began in Damascus in the 1960s, in the historic Souq Al-Bzouriyah, a market renowned for generations for its spices, herbs and traditional goods.

It was here that Saeed Jleilati built his business and developed a deep understanding of the spice trade. His work went far beyond simply buying and selling. Through years of experience, he learned how to recognise quality, understand different origins and select products for their aroma, freshness and character.

The family sourced products from around the world and supplied customers throughout Damascus and other Syrian cities, as well as markets beyond Syria, including Lebanon, Jordan, Egypt and the Gulf region. What began largely as a wholesale trade later expanded into retail within the same historic market.

Knowledge Passed Through Generations

Saeed's son, Wajih Jleilati, began working alongside his father while he was still actively running the business. Over the years, Wajih learned the trade firsthand and gradually assumed greater responsibility as his father grew older.

What passed from one generation to the next was more than a business — it was knowledge built through decades of experience.

The Jleilati family understands that two products carrying the same name are not necessarily equal. Climate, origin, harvest and freshness all influence quality. Knowing where to source a particular spice, how to recognise its quality and which suppliers to trust is knowledge developed over years, not overnight.

Anyone can sell spices. Understanding them is a different craft.

From Damascus to Germany

In 2011, the conflict in Syria led Wajih and his family to begin a new life in Germany. They settled in Saarbrücken, bringing with them the experience and passion developed over decades in Damascus.

There, Wajih returned to the trade he knew best and opened a retail store. What began by serving the local community gradually reached customers from different backgrounds. Syrian and Arab families found familiar flavours, while German and other European customers discovered the richness of the products and traditions behind them.

A New Generation

Today, the third generation of the Jleilati family is taking the next step: bringing the family tradition online.

The goal is to make their carefully selected products available beyond Saarbrücken, allowing customers across Europe to experience the same attention to quality and authenticity.

The places have changed.
The generations have changed.
The way people shop has changed.

But the knowledge behind the Jleilati name remains.`;

const ourStoryAr = `أجيال من الخبرة، من دمشق إلى أوروبا

بدأت حكاية جليلاتي في دمشق في ستينيات القرن الماضي، داخل سوق البزورية التاريخي، وهو سوق عُرف عبر الأجيال بالبهارات والأعشاب والمواد التقليدية.

هناك بنى سعيد جليلاتي عمله وطوّر فهماً عميقاً لعالم البهارات. لم يكن عمله مجرد بيع وشراء، بل خبرة في تمييز الجودة وفهم المنشأ واختيار المنتجات حسب الرائحة والطزاجة والطابع الخاص لكل صنف.

كانت العائلة تستورد وتختار منتجات من أنحاء مختلفة من العالم، وتخدم الزبائن في دمشق وبقية المدن السورية، إضافة إلى أسواق خارج سوريا مثل لبنان والأردن ومصر ودول الخليج. وما بدأ كتجارة جملة توسّع لاحقاً إلى البيع المباشر داخل السوق نفسه.

معرفة تنتقل بين الأجيال

بدأ وجيه جليلاتي، ابن سعيد، العمل إلى جانب والده وهو لا يزال يدير التجارة بنفسه. ومع السنوات تعلّم وجيه الحرفة من مصدرها، وتحمّل مسؤوليات أكبر مع تقدّم والده في العمر.

ما انتقل من جيل إلى جيل لم يكن مجرد تجارة، بل معرفة بُنيت عبر عقود من الخبرة.

تعرف عائلة جليلاتي أن منتجين يحملان الاسم نفسه لا يعنيان الجودة نفسها. المناخ والمنشأ والموسم والطزاجة كلها تؤثر على النتيجة. معرفة مصدر كل بهار، وكيفية تمييز جودته، ومن هم الموردون الموثوقون، هي خبرة لا تُبنى بين ليلة وضحاها.

أي شخص يستطيع بيع البهارات. أما فهمها فهو حرفة مختلفة.

من دمشق إلى ألمانيا

في عام 2011، دفعت الحرب في سوريا وجيه وعائلته لبدء حياة جديدة في ألمانيا. استقروا في ساربروكن، حاملين معهم خبرة وشغفاً تشكّلا على مدى عقود في دمشق.

هناك عاد وجيه إلى المهنة التي يعرفها جيداً وافتتح متجراً للبيع المباشر. بدأ بخدمة المجتمع المحلي، ثم وصل إلى زبائن من خلفيات مختلفة. وجدت العائلات السورية والعربية النكهات المألوفة، بينما اكتشف الزبائن الألمان والأوروبيون جودة المنتجات وعمق التقاليد خلفها.

جيل جديد

اليوم يأخذ الجيل الثالث من عائلة جليلاتي الخطوة التالية: نقل تقليد العائلة إلى الإنترنت.

الهدف هو إتاحة المنتجات المختارة بعناية خارج ساربروكن، ليصل نفس الاهتمام بالجودة والأصالة إلى العملاء في أوروبا.

تغيّرت الأماكن.
تغيّرت الأجيال.
وتغيّرت طريقة التسوق.

لكن المعرفة خلف اسم جليلاتي بقيت كما هي.`;

