const savedProducts = JSON.parse(localStorage.getItem("jleilatiCustomProducts") || "[]");
savedProducts.forEach((product) => products.push({ ...product, hidden: false }));
let hiddenProductIds = new Set();
try {
  hiddenProductIds = new Set(JSON.parse(localStorage.getItem("jleilatiHiddenProducts") || "[]"));
} catch (error) {
  hiddenProductIds = new Set();
}
for (let index = products.length - 1; index >= 0; index -= 1) {
  if (hiddenProductIds.has(products[index].id) || products[index].hidden) products.splice(index, 1);
}
const adminInventory = JSON.parse(localStorage.getItem("jleilatiInventory") || "{}");
products.forEach((product) => {
  if (!Object.prototype.hasOwnProperty.call(adminInventory, product.id)) return;
  const gramsAvailable = Math.max(0, Number(adminInventory[product.id]) || 0);
  const variants = product.variants || [];
  if (!variants.length) return;
  if (gramsAvailable <= 0) {
    variants.forEach((variant) => {
      variant.stock = 0;
    });
    return;
  }
  variants.forEach((variant) => {
    const grams = Math.max(1, Number(variant.grams) || 1);
    variant.stock = Math.max(0, Math.floor(gramsAvailable / grams));
  });
});
const productImageOverrides = JSON.parse(localStorage.getItem("jleilatiProductImages") || "{}");
const productNameOverrides = JSON.parse(localStorage.getItem("jleilatiProductNames") || "{}");
const productDescriptionOverrides = JSON.parse(localStorage.getItem("jleilatiProductDescriptions") || "{}");
const defaultTestUser = {
  firstName: "Mohamad",
  secondName: "Albi",
  email: "mohalbi123@hotmail.com",
  password: "12345",
  phone: "+49 176 63719858",
  street: "Breite Str. 14",
  city: "Saarbrücken",
  postalCode: "66115",
  country: "Germany",
  countryCode: "DE",
  address: "Breite Str. 14, 66115 Saarbrücken, Germany",
};

const publicConfig = window.JLEILATI_CONFIG || {};
const integrations = {
  googleClientId: publicConfig.googleClientId || localStorage.getItem("jleilatiGoogleClientId") || "",
  stripePublishableKey: publicConfig.stripePublishableKey || localStorage.getItem("jleilatiStripePublishableKey") || "",
  shippingProvider: "DHL",
};

async function loadLiveIntegrations() {
  try {
    const response = await fetch("/api/config", { cache: "no-store" });
    if (!response.ok) return;
    const config = await response.json();
    integrations.googleClientId = config.googleClientId || integrations.googleClientId;
    integrations.stripePublishableKey = config.stripePublishableKey || integrations.stripePublishableKey;
  } catch (error) {
    // Local static preview has no Vercel API route; config.js/localStorage still work there.
  }
}

function loadCart() {
  try {
    const parsed = JSON.parse(localStorage.getItem("jleilatiCart") || "[]");
    if (!Array.isArray(parsed)) return [];
    return parsed
      .filter((item) => item && item.productId && item.variantId && Number(item.quantity) > 0)
      .map((item) => ({
        productId: String(item.productId),
        variantId: String(item.variantId),
        quantity: Math.max(1, Number(item.quantity) || 1),
      }));
  } catch (error) {
    return [];
  }
}

function saveCart() {
  localStorage.setItem("jleilatiCart", JSON.stringify(state.cart));
}

function cleanUrlHash() {
  if (!window.location.hash) return;
  window.history.replaceState(null, "", `${window.location.pathname}${window.location.search}`);
}

function scrollToSection(selector) {
  const target = document.querySelector(selector);
  if (target) target.scrollIntoView({ behavior: "smooth", block: "start" });
  cleanUrlHash();
}

function loadUsers() {
  let users = [];
  try {
    users = JSON.parse(localStorage.getItem("jleilatiUsers") || "[]");
  } catch (error) {
    users = [];
  }
  users = users
    .filter((user) => user && user.email)
    .map((user) => ({ ...user, email: String(user.email).trim().toLowerCase() }));

  const defaultEmail = defaultTestUser.email.toLowerCase();
  const testUserIndex = users.findIndex((user) => user.email === defaultEmail);
  if (testUserIndex >= 0) {
    users[testUserIndex] = {
      ...defaultTestUser,
      ...users[testUserIndex],
      email: defaultEmail,
      password: defaultTestUser.password,
    };
  } else {
    users.push({ ...defaultTestUser, email: defaultEmail });
  }
  localStorage.setItem("jleilatiUsers", JSON.stringify(users));
  return users;
}

function saveUsers(users) {
  localStorage.setItem("jleilatiUsers", JSON.stringify(users));
}

function seedTestOrders() {
  const orders = JSON.parse(localStorage.getItem("jleilatiOrders") || "[]");
  if (orders.some((order) => (order.customer?.email || "").toLowerCase() === defaultTestUser.email.toLowerCase())) return;
  const sampleOrders = [
    {
      id: 1201,
      createdAt: new Date().toISOString(),
      status: "in_progress",
      notification: "Admin email queued: saeedjleilati@gmail.com",
      customer: {
        firstName: defaultTestUser.firstName,
        secondName: defaultTestUser.secondName,
        email: defaultTestUser.email,
        phone: defaultTestUser.phone,
        address: defaultTestUser.address,
      },
      totals: { subtotal: 42, shipping: 10, total: 52 },
      lines: [{ productId: "spices-001", productName: "زنجبيل حب", weight: "500 g", grams: 500, quantity: 1, lineTotal: 8 }],
    },
    {
      id: 1184,
      createdAt: new Date(Date.now() - 1000 * 60 * 60 * 24 * 12).toISOString(),
      status: "sent",
      notification: "Order shipped",
      customer: {
        firstName: defaultTestUser.firstName,
        secondName: defaultTestUser.secondName,
        email: defaultTestUser.email,
        phone: defaultTestUser.phone,
        address: defaultTestUser.address,
      },
      totals: { subtotal: 67, shipping: 0, total: 67 },
      lines: [{ productId: "nuts-001", productName: "لوز ني", weight: "1 kg", grams: 1000, quantity: 1, lineTotal: 15 }],
    },
  ];
  localStorage.setItem("jleilatiOrders", JSON.stringify([...sampleOrders, ...orders].slice(0, 25)));
}

const users = loadUsers();
seedTestOrders();
const savedAccountEmail = localStorage.getItem("jleilatiCurrentUser");
const savedAccount = users.find((user) => user.email === savedAccountEmail) || null;

const state = {
  lang: localStorage.getItem("jleilatiLang") || "en",
  category: "all",
  searchQuery: "",
  activeSearchInput: "headerSearch",
  authTab: "signin",
  cart: loadCart(),
  pendingCheckout: false,
  account: savedAccount || { ...defaultTestUser },
};

