function t(key, params = {}) {
  const activeDictionary = i18n[state.lang] || i18n.en;
  const hardFallback = {
    acceptPolicies: {
      ar: "أوافق على الأحكام والشروط وسياسة ملفات تعريف الارتباط.",
      de: "Ich akzeptiere die Bedingungen und die Cookie-Richtlinie.",
      fr: "J'accepte les conditions et la politique relative aux cookies.",
      en: "I accept the terms, conditions and cookie policy.",
    },
    privacyPolicy: {
      ar: "سياسة الخصوصية",
      de: "Datenschutzerklärung",
      fr: "Politique de confidentialité",
      en: "Privacy policy",
    },
  };
  let value = Object.prototype.hasOwnProperty.call(activeDictionary, key)
    ? activeDictionary[key]
    : Object.prototype.hasOwnProperty.call(i18n.en, key)
      ? i18n.en[key]
      : key;
  if (value === key && hardFallback[key]) {
    value = hardFallback[key][state.lang] || hardFallback[key].en;
  }
  Object.entries(params).forEach(([name, replacement]) => {
    value = value.replace(`{${name}}`, replacement);
  });
  return value;
}

function localize(value) {
  return value[state.lang] || value.en || value.ar;
}

function hasArabicText(value) {
  return /[\u0600-\u06ff]/.test(String(value || ""));
}

